-- Rifts World Book 13: Lone Star - its gear. Twelve new rows from the Dog Boy
-- Equipment chapter: five Vibro-Blade Vambraces (printed 48-49), the two
-- Electro-Stunners (49-50), the Rope Pole (50-51), the CN-1 Net Gun (51), the
-- Mutant Animal Restraining Harness (51-52) and the two DPM environmental
-- armors (52-53).
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-lone-star-gear.sql
--
-- ALL 12 ARE NEW - catalog-diff --table gear --remote, 2026-10-01. The rest of
-- the chapter is held from other books and is left alone; see
-- docs/surveys/lone-star.md for the false gaps (the C-27 "Light" Plasma Cannon
-- is the catalog's C-27 under the class the book says it was moved to).
--
-- THE DPM D1 AND D2 PRINT ONE LOCATION BLOCK for both suits, differing only
-- in the main body. The helmet, arm and leg figures are that block's.
--
-- THE TEXT LAYER PRINTS TWO FIGURES AS LETTERS: the Cat's Claw price and the
-- ES-20's strong shock. Read as 11,000 and 1D4x10, the only values they can be.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book) VALUES
('vibro-vambrace-short-spiked-handguard', 'Vibro-Blade Vambrace: Short, Spiked Blade Handguard', 'rifts', 'weapon', NULL, 9000, NULL, '2D4 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A Dog Boy forearm vambrace fitted with vibro-blades; part of DPM riot armor or the full environmental suit. Only one set of blades, hand or forearm, can be used at a time, so carrying both does not add damage. Two short serrated blades for slashing and stabbing, and for sawing through light M.D.C. wire, plastic and ceramics or S.D.C. metal and concrete.', 'Rifts World Book 13: Lone Star p.48'),
('vibro-vambrace-cats-claw-handguard', 'Vibro-Blade Vambrace: Triple Bladed "Cat''s Claw" Handguard', 'rifts', 'weapon', NULL, 11000, NULL, '3D4 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A Dog Boy forearm vambrace fitted with vibro-blades; part of DPM riot armor or the full environmental suit. Only one set of blades, hand or forearm, can be used at a time, so carrying both does not add damage. Three curved, claw-like blades.', 'Rifts World Book 13: Lone Star p.48'),
('vibro-vambrace-dual-long-blade-handguard', 'Vibro-Blade Vambrace: Dual Long-Blade Handguard', 'rifts', 'weapon', NULL, 11000, NULL, '2D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A Dog Boy forearm vambrace fitted with vibro-blades; part of DPM riot armor or the full environmental suit. Only one set of blades, hand or forearm, can be used at a time, so carrying both does not add damage. A pair of long blades that retract to half length; 10 inches at full extension. For slashing, stabbing and parrying.', 'Rifts World Book 13: Lone Star p.48'),
('vibro-vambrace-hooked-forearm-blades', 'Vibro-Blade Vambrace: Hooked Forearm Vibro-Blades', 'rifts', 'weapon', NULL, 14500, NULL, '2D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A Dog Boy forearm vambrace fitted with vibro-blades; part of DPM riot armor or the full environmental suit. Only one set of blades, hand or forearm, can be used at a time, so carrying both does not add damage. A pair of hooked blades that retract to half length; 20-24 inches at full extension. +1 to parry and +2 to disarm; +5% to the Climbing skill.', 'Rifts World Book 13: Lone Star p.49'),
('vibro-vambrace-sabre-forearm-blades', 'Vibro-Blade Vambrace: Sabre Forearm Vibro-Blades', 'rifts', 'weapon', NULL, 16000, NULL, '2D6+2 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A Dog Boy forearm vambrace fitted with vibro-blades; part of DPM riot armor or the full environmental suit. Only one set of blades, hand or forearm, can be used at a time, so carrying both does not add damage. A pair of straight blades that retract to half length; 24 inches at full extension. +1 to parry.', 'Rifts World Book 13: Lone Star p.49'),
('es-10-electro-stun-hand-prod', 'ES-10 Electro-Stun Hand Prod', 'rifts', 'weapon', NULL, 6500, NULL, 'Shock, three settings: light 1D4 S.D.C., moderate 2D6 S.D.C., strong 5D6 S.D.C. As a club 2D4 S.D.C. plus P.S. bonus; jabbing 1D4 S.D.C.', 0, NULL, '50 strong blasts or 100 moderate; rechargeable', NULL, NULL, NULL, 50, 'A two-foot Lone Star Complex shock rod for handling animals, mutants and prisoners. The tooth end must touch the target. The shock passes through metal and most S.D.C. armor to the wearer without harming the armor; it does nothing against environmental M.D.C. armor, power armor, robots or bionics, but works on Dog Pack riot armor, half suits and a suit worn without its helmet. The strong setting has a 01-33% chance to stun humans, D-Bees and small animals for 1D4 melee rounds (01-03% against large or inhumanly powerful animals). Stunned victims are -6 to strike, parry and dodge at half speed and half attacks, for 1D4 melee rounds, plus 1D4 per further failed save. More than five strong shocks, or hit points below half, may knock the victim out for 2D4 melee rounds; with S.D.C. gone and 8 hit points or fewer there is a 01-60% chance of cardiac arrest. The rod is an M.D.C. structure and can parry M.D. attacks. The strong setting only: save vs electric shock, 15 or higher; a save halves the damage and costs initiative and one attack.', 'Rifts World Book 13: Lone Star p.49-50'),
('es-20-electro-stun-spear', 'ES-20 Electro-Stun Spear', 'rifts', 'weapon', NULL, 12000, NULL, 'Shock, three settings: light 1D6 S.D.C., moderate 3D6 S.D.C., strong 1D4x10 S.D.C. As a club 2D4+2 S.D.C. plus P.S. bonus; jabbing 1D6 S.D.C.', 0, NULL, '50 strong blasts or 100 moderate; rechargeable', NULL, NULL, NULL, 80, 'A spear-length electro-prod, 6 feet 6 inches long, for dangerous or large animals where distance is wanted. Works as the ES-10 with a stronger shock: the strong setting has a 01-65% chance to stun humans, D-Bees and small animals for 1D4 melee rounds (01-20% against giant or inhumanly powerful animals). Stunned victims are -8 to strike, parry and dodge at half speed and half attacks. More than three strong shocks, or hit points below half, may knock the victim out for 2D4 melee rounds; with S.D.C. gone and 12 hit points or fewer there is a 01-70% chance of cardiac arrest. Useless against environmental M.D.C. armor, power armor, robots and cyborgs. The spear is an M.D.C. structure and can parry M.D. attacks. The strong setting only: save vs electric shock, 15 or higher; a save halves the damage and costs initiative and one attack.', 'Rifts World Book 13: Lone Star p.50'),
('rope-pole', 'Rope Pole', 'rifts', 'weapon', NULL, 2500, NULL, 'As a club 1D6 S.D.C. plus P.S. bonus; jabbing 1D4 S.D.C. The noose strangles rather than wounds.', 0, NULL, NULL, NULL, NULL, NULL, 35, 'The "Strangle Rod": a 6 foot 6 inch M.D.C. pole with a noose at the end and 20 feet of M.D.C. cord inside, used to capture and control animals, mutants and prisoners. The cord holds 800 pounds; a P.S. of 35 or higher snaps it, and it has one M.D.C. per square inch. The noose tightens when the captive struggles. An average human passes out after 2-3 minutes, at half combat bonuses and one attack fewer per round meanwhile, and usually dies after another 1D4 minutes; large animals and mutants take 1D4+1 minutes. A captive recovers 1D4 minutes after the noose is loosened. The hollow pole can parry M.D. attacks but snaps more easily than a solid weapon.', 'Rifts World Book 13: Lone Star p.50-51'),
('cn-1-net-gun', 'CN-1 Net Gun', 'rifts', 'weapon', 10, 8000, 'The gun with two compressed air cartridges. An M.D.C. net with its reusable firing cartridge is 4,000 credits and an S.D.C. net 800. Repacking a net at the factory is 1,000 credits for M.D.C. and 300 for S.D.C.', 'None; entangles', 0, '40 feet', 'One net; the air cartridge fires six nets', 'Once per melee round; twice with a quick reload', NULL, NULL, NULL, 'A bulky, light gun that fires a cartridge releasing a net big enough for a creature twice human size. An average person needs 1D4 minutes to work loose, most animals 3D4 minutes, most supernatural beings 5D6 seconds. The M.D.C. net has one M.D.C. per square inch (the S.D.C. net two S.D.C.) and takes at least two melee rounds to cut through with an M.D. blade. Reloading a net takes 2-3 melee actions; the air cartridge a full melee round.', 'Rifts World Book 13: Lone Star p.51'),
('mutant-animal-restraining-harness', 'Mutant Animal Restraining Harness', 'rifts', 'gear', NULL, 2000, 'Not commonly available to adventurers; 20-40% more when it is.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 40, 'A Coalition straitjacket reinforced with M.D.C. clamps, braces and cords. Breaking out needs a P.S. of 40 or higher, or a supernatural P.S. of 22. It folds and holds the arms: attacks per melee are halved and running speed drops by a third; -30% to Escape Artist. The optional muzzle stops biting and talking and can carry a slow-release tranquilizer gas (save vs nonlethal toxins, 16 or higher, each minute) that removes initiative and halves combat bonuses, attacks, speed and skills.', 'Rifts World Book 13: Lone Star p.51-52'),
('dpm-d1-heavy-dog-boy-armor', 'DPM D1 Heavy Dog Boy Armor', 'rifts', 'armor', 18, NULL, 'Not available; exclusive to the CS military.', '2D6 or 2D6+2 M.D. (forearm Vibro-Sabres)', 1, NULL, NULL, NULL, NULL, NULL, 80, 'The old CA-1 heavy "Dead Boy" environmental armor with a helmet shaped for a canine head; issued to Dog Pack officers, veterans, elite squads and Special Forces. M.D.C. by location: main body 80, helmet 50, arms 35 each, legs 50 each. Good mobility: -10% to Climbing and -25% to Prowl, Swimming, Acrobatics and similar. Each forearm has a pair of fully retractable Vibro-Sabres. Full environmental armor with a five-hour oxygen supply, a removable face plate and a five-mile helmet radio.', 'Rifts World Book 13: Lone Star p.52-53'),
('dpm-d2-light-dog-boy-armor', 'DPM D2 Light Dog Boy Armor', 'rifts', 'armor', 9, NULL, 'Not available; exclusive to the CS military.', '2D6 or 2D6+2 M.D. (forearm Vibro-Sabres)', 1, NULL, NULL, NULL, NULL, NULL, 50, 'The old CA-2 light "Dead Boy" environmental armor with a helmet shaped for a canine head; issued to about three quarters of Dog Pack infantry by 105 P.A. M.D.C. by location: main body 50, helmet 50, arms 35 each, legs 50 each. Very good mobility: -5% to Climbing and -10% to Prowl, Swimming, Acrobatics and similar. Each forearm has a pair of fully retractable Vibro-Sabres. Full environmental armor with a five-hour oxygen supply, a removable face plate and a five-mile helmet radio.', 'Rifts World Book 13: Lone Star p.52-53');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 12 Lone Star gear rows are in' AS assertion, count(*) AS got, 12 AS want
  FROM gear WHERE slug IN ('vibro-vambrace-short-spiked-handguard', 'vibro-vambrace-cats-claw-handguard', 'vibro-vambrace-dual-long-blade-handguard', 'vibro-vambrace-hooked-forearm-blades', 'vibro-vambrace-sabre-forearm-blades', 'es-10-electro-stun-hand-prod', 'es-20-electro-stun-spear', 'rope-pole', 'cn-1-net-gun', 'mutant-animal-restraining-harness', 'dpm-d1-heavy-dog-boy-armor', 'dpm-d2-light-dog-boy-armor');
SELECT 'and every one cites Lone Star' AS assertion, count(*) AS got, 12 AS want
  FROM gear WHERE slug IN ('vibro-vambrace-short-spiked-handguard', 'vibro-vambrace-cats-claw-handguard', 'vibro-vambrace-dual-long-blade-handguard', 'vibro-vambrace-hooked-forearm-blades', 'vibro-vambrace-sabre-forearm-blades', 'es-10-electro-stun-hand-prod', 'es-20-electro-stun-spear', 'rope-pole', 'cn-1-net-gun', 'mutant-animal-restraining-harness', 'dpm-d1-heavy-dog-boy-armor', 'dpm-d2-light-dog-boy-armor') AND source_book LIKE 'Rifts World Book 13: Lone Star p.%';

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('add-lone-star-gear.sql');
